  .word LEVEL2_RoomDataTable
  .byte 2 ; LEVEL2 rooms
  .byte LEVEL3_START_ROOM, LEVEL3_MINER_ROOM, LEVEL3_MINER_X, LEVEL3_MINER_Y, LEVEL3_WALL_COLOR, LEVEL3_WALL_COLOR2
  .word LEVEL3_RoomDataTable
